function collectSideEffects(src) {
    var effects = [];
    var seen = {};

    var patterns = [
        { re: /jira_move_to_status\s*\(\s*\{[^}]*statusName:\s*(['"`])([^'"`]+)\1/g, label: 'move ticket to status "$2"' },
        { re: /jira_transition_to_status\s*\(\s*\{[^}]*statusName:\s*(['"`])([^'"`]+)\1/g, label: 'transition ticket to status "$2"' },
        { re: /jira_add_label\s*\(\s*\{[^}]*label:\s*(['"`])([^'"`]+)\1/g, label: 'add label "$2"' },
        { re: /jira_remove_label\s*\(\s*\{[^}]*label:\s*(['"`])([^'"`]+)\1/g, label: 'remove label "$2"' },
        { re: /jira_update_field\s*\(\s*\{[^}]*field:\s*(['"`])([^'"`]+)\1/g, label: 'update field "$2"' },
        { re: /jira_post_comment\s*\(/g, label: 'post Jira comment' },
        { re: /jira_create_ticket_with_json\s*\(/g, label: 'create Jira ticket' },
        { re: /jira_create_issue\s*\(/g, label: 'create Jira issue' },
        { re: /jira_link_issues\s*\(/g, label: 'link Jira issues' },
        { re: /jira_assign_ticket_to\s*\(/g, label: 'assign ticket' },
        { re: /jira_attach_file_to_ticket\s*\(/g, label: 'attach file to ticket' },
        // Tracker-agnostic layer (js/common/trackers.js): same side effects,
        // dispatched onto jira_* / ado_* / github_* tools at runtime.
        { re: /tracker\.addLabel\s*\([^,]+,\s*(['"`])([^'"`]+)\1\s*\)/g, label: 'add label "$2" (via tracker)' },
        { re: /tracker\.removeLabel\s*\([^,]+,\s*(['"`])([^'"`]+)\1\s*\)/g, label: 'remove label "$2" (via tracker)' },
        { re: /tracker\.postComment\s*\(/g, label: 'post ticket comment (via tracker)' },
        { re: /tracker\.moveToStatus(?:OrMark)?\s*\(/g, label: 'move ticket to status (via tracker)' },
        { re: /tracker\.assignTo\s*\(/g, label: 'assign ticket (via tracker)' },
        { re: /tracker\.createTicket\s*\(/g, label: 'create ticket (via tracker)' },
        { re: /github_create_pr\s*\(/g, label: 'create GitHub PR' },
        { re: /github_create_pull_request\s*\(/g, label: 'create GitHub PR' },
        { re: /github_merge_pr\s*\(/g, label: 'merge GitHub PR' },
        { re: /github_merge_pull_request\s*\(/g, label: 'merge GitHub PR' },
        { re: /github_post_review_comment\s*\(/g, label: 'post PR review comment' },
        { re: /github_create_review_comment\s*\(/g, label: 'post PR review comment' },
        { re: /github_update_pr\s*\(/g, label: 'update PR' },
        { re: /github_close_pr\s*\(/g, label: 'close PR' },
        { re: /git push/g, label: 'git push' },
        { re: /git checkout/g, label: 'git checkout' },
        { re: /git merge/g, label: 'git merge' },
        { re: /git rebase/g, label: 'git rebase' }
    ];

    patterns.forEach(function(pattern) {
        var match;
        while ((match = pattern.re.exec(src)) !== null) {
            var captures = [];
            for (var i = 2; i < match.length; i++) {
                if (match[i] !== undefined) captures.push(match[i]);
            }
            var label = renderSideEffect(pattern.label, captures);
            if (!seen[label]) {
                seen[label] = true;
                effects.push(label);
            }
        }
    });

    return effects;
}

/**
 * Extract customParams paths used by a JS action source, e.g.
 *   customParams.foo            → foo

/**
 * Shared helpers for the story test-automation post-actions
 * (js/postStoryTestAutomationResults.js, js/postStoryTestAutomationReview.js).
 *
 * Extracted in the gh-1008 CRAP split: the tracker lazy-init holder,
 * resume-attempt markers, markdown→Jira-wiki conversion, quiet label removal
 * and the git publish/push operations. Behavior and posted strings stay
 * byte-identical to the originals — they are posted verbatim to the tracker.
 *
 * The git ops take the pullRequest helper as a factory argument so test
 * suites inject the same instance the calling module uses. Every function
 * stays ≤ CC 8 so the per-function CRAP ratchet (new keys must be ≤ 8)
 * holds even before coverage is applied.
 */

/**
 * Tracker-agnostic ticket operations holder (jira / ado / github): creates
 * the tracker lazily per action() run and resets on re-init, replacing the
 * module-level _trackerCtx/_trackerInst singletons both post-actions used to
 * duplicate.
 */
function createTrackerHolder(trackersModule) {
    var ctx = { config: null, customParams: {} };
    var inst = null;
    return {
        initTracker: function(config, customParams) {
            ctx = { config: config || null, customParams: customParams || {} };
            inst = null;
        },
        getTracker: function() {
            if (!inst) inst = trackersModule.createTracker(ctx.config, ctx.customParams);
            return inst;
        }
    };
}

function readAttemptMarker(markerPath) {
    try {
        var raw = file_read({ path: markerPath });
        var value = parseInt(raw || '0', 10);
        return isNaN(value) ? 0 : value;
    } catch (e) {
        return 0;
    }
}

function writeAttemptMarker(markerPath, attempt) {
    try {
        file_write({ path: markerPath, content: String(attempt) });
    } catch (e) {
        console.warn('Could not write resume attempt marker:', e);
    }
}

function markdownToJiraWiki(markdown) {
    if (!markdown) return '';
    var text = String(markdown);
    text = text.replace(/```(\w+)?\n([\s\S]*?)```/g, function(_, language, code) {
        return '{code' + (language ? ':' + language : '') + '}\n' + code.trim() + '\n{code}';
    });
    text = text
        .replace(/^####\s+(.+)$/gm, 'h4. $1')
        .replace(/^###\s+(.+)$/gm, 'h3. $1')
        .replace(/^##\s+(.+)$/gm, 'h2. $1')
        .replace(/^#\s+(.+)$/gm, 'h1. $1')
        .replace(/^\s*-\s+/gm, '* ')
        .replace(/\*\*([^*\n]+)\*\*/g, '*$1*')
        .replace(/`([^`\n]+)`/g, '{{$1}}')
        .replace(/\[([^\]\n]+)\]\((https?:\/\/[^)\s]+)\)/g, '[$1|$2]');
    return text.trim();
}

function removeLabelSafely(getTracker, key, label) {
    try {
        getTracker().removeLabel(key, label);
        return true;
    } catch (e) {
        return false;
    }
}

function runInRepo(command, workingDir) {
    var args = { command: command };
    if (workingDir) args.workingDirectory = workingDir;
    return cli_execute_command(args);
}

/**
 * Git publish/push operations shared by the story test-automation post-action.
 * All functions take (branchName|…, workingDir) and never throw — failures
 * are reported as { success: false, error } result objects or false.
 */
function createGitOps(prHelper) {
    function cleanCommandOutput(output) {
        return prHelper.cleanCommandOutput(output);
    }

    function fetchRemoteBranch(branchName, workingDir) {
        try {
            runInRepo('git fetch origin ' + branchName, workingDir);
            return true;
        } catch (e) {
            console.warn('Could not fetch remote branch origin/' + branchName + ':', e);
            return false;
        }
    }

    function revParse(ref, workingDir) {
        try {
            return cleanCommandOutput(runInRepo('git rev-parse ' + ref, workingDir) || '').trim();
        } catch (e) {
            return '';
        }
    }

    function findMergeBase(left, right, workingDir) {
        try {
            return cleanCommandOutput(runInRepo('git merge-base ' + left + ' ' + right, workingDir) || '').trim();
        } catch (e) {
            return '';
        }
    }

    function sameHead(localSha, remoteSha) {
        return !!(localSha && remoteSha && localSha === remoteSha);
    }

    function isAheadOfRemote(mergeBase, remoteSha, localSha) {
        return !!(mergeBase && mergeBase === remoteSha && mergeBase !== localSha);
    }

    function isBehindRemote(mergeBase, remoteSha, localSha) {
        return !!(mergeBase && mergeBase === localSha && mergeBase !== remoteSha);
    }

    /**
     * Pure sync decision for a branch whose local/remote shas are known:
     * 'identical' | 'ahead' (fast-forward) | 'behind' (adopt remote) | 'diverged'.
     */
    function syncDecision(localSha, remoteSha, mergeBase) {
        if (sameHead(localSha, remoteSha)) return 'identical';
        if (isAheadOfRemote(mergeBase, remoteSha, localSha)) return 'ahead';
        if (isBehindRemote(mergeBase, remoteSha, localSha)) return 'behind';
        return 'diverged';
    }

    function pushBranchWithLease(branchName, workingDir) {
        try {
            runInRepo('git push -u origin ' + branchName, workingDir);
            return { success: true, noNewCommit: true };
        } catch (pushErr) {
            console.log('Normal push failed, retrying with --force-with-lease...');
            try {
                runInRepo('git push -u origin ' + branchName + ' --force-with-lease', workingDir);
                return { success: true, noNewCommit: true };
            } catch (forcePushErr) {
                console.warn('Failed to publish existing branch:', forcePushErr);
                return { success: false, error: 'No test files were written and the synced branch could not be pushed' };
            }
        }
    }

    function publishExistingBranch(branchName, workingDir) {
        // Ensure the local remote-tracking ref is fresh before any push decision.
        fetchRemoteBranch(branchName, workingDir);

        var localSha = revParse('HEAD', workingDir);
        var remoteSha = revParse('origin/' + branchName, workingDir);
        var mergeBase = (localSha && remoteSha) ? findMergeBase('HEAD', 'origin/' + branchName, workingDir) : '';

        var decision = syncDecision(localSha, remoteSha, mergeBase);

        if (decision === 'identical') {
            console.log('Local branch already matches origin/' + branchName + '; no push needed');
            return { success: true, noNewCommit: true };
        }

        if (decision === 'ahead') {
            // Local is strictly ahead of remote (fast-forward).
            try {
                runInRepo('git push -u origin ' + branchName, workingDir);
                return { success: true, noNewCommit: true };
            } catch (e) {
                console.warn('Fast-forward push failed:', e);
            }
        } else if (decision === 'behind') {
            // Remote moved ahead while we had no local changes to keep. Adopt remote state.
            console.log('Remote ' + branchName + ' is ahead of local branch; resetting to origin/' + branchName);
            runInRepo('git reset --hard origin/' + branchName, workingDir);
            return { success: true, noNewCommit: true };
        }

        // Branches diverged (or the fast-forward push failed); push with refreshed lease.
        return pushBranchWithLease(branchName, workingDir);
    }

    /**
     * Logs the working-tree state and stages the test path.
     * Returns the `git diff --cached --stat` output (empty when nothing staged).
     */
    function inspectAndStage(addPath, inspectPath, workingDir) {
        try {
            var lsOutput = runInRepo('git status --short -- ' + inspectPath, workingDir) || '';
            console.log('Git status for ' + inspectPath + ':', cleanCommandOutput(lsOutput) || '(empty)');
        } catch (e) {
            console.warn('Could not list ' + inspectPath + ':', e);
        }

        console.log('Staging test path:', addPath);
        runInRepo('git add ' + addPath, workingDir);

        return cleanCommandOutput(runInRepo('git diff --cached --stat', workingDir) || '');
    }

    /**
     * Nothing new to commit: publis…

/**
 * Post Story Test Automation Results Action
 * 1. Reads outputs/story_test_automation_result.json
 * 2. Commits/pushes testing/ folder on test/{STORY_KEY} branch
 * 3. Creates PR to main
 * 4. Per linked Test Case:
 *    - status → In Review - Passed / In Review - Failed
 *    - failed TC: attach outputs/failed_description_{TC_KEY}.md and set Failed Reason field
 * 5. Moves Story → In Testing
 * 6. Triggers pr_story_test_automation_review
 *
 * gh-1008 CRAP split: tracker/git/marker/wiki helpers live in
 * js/postStoryTestAutomationShared.js; action() is a thin orchestrator.
 */

var configLoader = require('./configLoader.js');
var prHelper = require('./common/pullRequest.js');
var autoStart = require('./common/autoStart.js');
const { GIT_CONFIG, LABELS, JIRA_FIELDS } = require('./config.js');
var outputFiles = require('./common/outputFiles.js');
var tokenUsageComment = require('./common/tokenUsageComment.js');
var shared = require('./postStoryTestAutomationShared.js');

// Tracker-agnostic ticket operations (jira / ado / github) — created lazily per action() run.
var trackersModule = require('./common/trackers.js');
var trackerHolder = shared.createTrackerHolder(trackersModule);
function initTracker(config, customParams) {
    trackerHolder.initTracker(config, customParams);
}
function getTracker() {
    return trackerHolder.getTracker();
}

var gitOps = shared.createGitOps(prHelper);
var runInRepo = shared.runInRepo;

var RESUME_MARKER = 'outputs/.story-test-resume-attempted';

function cleanCommandOutput(output) {
    return prHelper.cleanCommandOutput(output);
}

function readFile(path) {
    return outputFiles.readOutputFile(path, {});
}

function readOutputFile(relativePath, workingDir, ticketKey) {
    return outputFiles.readOutputFile(relativePath, {
        workingDir: workingDir,
        ticketKey: ticketKey
    });
}

function readResultJson(workingDir, storyKey) {
    try {
        const raw = readOutputFile('story_test_automation_result.json', workingDir, storyKey);
        if (!raw) {
            console.warn('outputs/story_test_automation_result.json is empty or missing');
            return null;
        }
        const rawString = String(raw);
        try {
            const parsed = JSON.parse(rawString);
            console.log('Story test result overall:', parsed.overall);
            return parsed;
        } catch (parseErr) {
            console.error('Failed to parse story_test_automation_result.json:', parseErr);
            console.error('Raw content preview (first 1000 chars):', rawString.substring(0, 1000));
            console.error('Raw content preview around error:', rawString.substring(Math.max(0, parseErr.pos - 100), parseErr.pos + 100));
            return null;
        }
    } catch (e) {
        console.error('Failed to read story_test_automation_result.json:', e);
        return null;
    }
}

function readLinkedTestCases(storyKey, testCaseType) {
    try {
        var raw = readFile('input/' + storyKey + '/linked_test_cases.json');
        if (raw) {
            var parsed = JSON.parse(raw);
            if (parsed && Array.isArray(parsed.testCases)) {
                console.log('Loaded', parsed.testCases.length, 'linked Test Case(s) from input folder');
                return parsed.testCases;
            }
        }
    } catch (e) {
        console.warn('Could not read linked_test_cases.json, falling back to JQL:', e);
    }

    try {
        var jql = 'issue in linkedIssues("' + storyKey + '") AND issuetype = "' + testCaseType + '"';
        // JQL text: provider-specific query (WIQL on ado)
        var results = getTracker().searchIssues(jql, { maxResults: 100, fields: ['key'] });
        return Array.isArray(results) ? results : [];
    } catch (e) {
        console.warn('Failed to fetch linked Test Cases from Jira:', e);
        return [];
    }
}

function getMissingTestCaseKeys(result, linkedTestCases) {
    var resultKeys = {};
    if (result && Array.isArray(result.results)) {
        result.results.forEach(function(r) {
            if (r.testCaseKey) resultKeys[r.testCaseKey] = true;
        });
    }
    return linkedTestCases
        .map(function(tc) { return tc.key; })
        .filter(function(key) { return key && !resultKeys[key]; });
}

function buildResumePrompt(storyKey, linkedTestCases, result, missingKeys) {
    var checkedKeys = [];
    if (result && Array.isArray(result.results)) {
        checkedKeys = result.results.map(function(r) { return r.testCaseKey; }).filter(Boolean);
    }

    var resultSchema = JSON.stringify({
        "$schema": "http://json-schema.org/draft-07/schema#",
        "type": "object",
        "required": ["storyKey", "overall", "summary", "results"],
        "properties": {
            "storyKey": { "type": "string", "const": storyKey },
            "overall": { "type": "string", "enum": ["passed", "failed", "in_progress"] },
            "summary": { "type": "string" },
            "results": {
                "type": "array",
                "items": {
                    "type": "object",
                    "required": ["testCaseKey", "status"],
                    "properties": {
                        "testCaseKey": { "type": "string", "pattern": "^TS-[0-9]+$" },
                        "status": { "type": "string", "enum": ["passed", "failed", "skipped", "irrelevant"] },
                        "testPath": { "type": "string" },
                        "failedDescriptionFile": { "type": "string" },
                        "failureSummary": { "type": "string" }
                    },
                    "additionalProperties": false
                }
            }
        },
        "additionalProperties": false
    }, null, 2);

    return 'RESUME TASK: The previous story test automation run did not verify all linked Test Cases.\n\n' +
        'Story: ' + storyKey + '\n' +
        'Linked Test Cases (' + linkedTestCases.length + '): ' + linkedTestCases.map(function(tc) { return tc.key; }).join(', ') + '\n' +
        'Already checked (' + checkedKeys.length + '): ' + (checkedKeys.join(', ') || 'none') + '\n' +
        'Still missing (' + missingKeys.length + '): ' + missingKeys.join(', ') + '\n\n' +
        'Instructions:\n' +
        '- Continue the same story test automation task in the same repository.\n' +
        '- For every missing Test Case, run/verify the corresponding automated test.\n' +
        '- Create or update outputs/story_test_automation_result.json with a top-level object that matches the JSON Schema below.\n' +
        '- Append a result entry for each missing Test Case:\n' +
        '  { "testCaseKey": "TS-XXX", "status": "passed" | "failed" | "skipped" | "irrelevant", "testPath": "testing/tests/TS-XXX/...", "failedDescriptionFile": "outputs/failed_description_TS-XXX.md", "failureSummary": "..." }\n' +
        '- If the result JSON file is missing, create it from scratch using the existing outputs/response.md and testing/tests/ files as evidence.\n' +
        '- If a test fails, write a failed description file and reference it in the result entry.\n' +
        '- Do NOT push changes; the post-action will commit and push after you finish.\n' +
        '- Do NOT move the Story to another status.\n' +
        '- Update outputs/response.md with a short summary of what was verified.\n' +
        '- Validate that outputs/story_test_automation_result.json is parseable JSON that conforms to the schema before stopping.\n\n' +
