        var testCaseType = (jiraConfig.issueTypes && jiraConfig.issueTypes.TEST_CASE) || 'Test Case';
        var linkedTestCases = readLinkedTestCases(storyKey, testCaseType);

        var result = readResultJson(workingDir, storyKey);
