            const branchMatch = prInfo.match(/\*\*Branch\*\*:\s*([^\s\n]+)/);
            if (numMatch) prNumber = parseInt(numMatch[1], 10);
            if (urlMatch) prUrl = urlMatch[1];
            if (branchMatch) prBranch = branchMatch[1];
        }
