    return {
        filePath: filePath,
        effectivePath: effectivePath,
        effectiveLine: effectiveLine,
        startLine: startLine,
        requestedSide: requestedSide,
        lineInfo: lineInfo,
        mappedFromSubmodule: mappedFromSubmodule
