                getTracker().postComment(storyKey, 'h3. ⚠️ Git Operations Failed\n\n' + gitResult.error);
                removeAutomationLabels(storyKey, params);
                return { success: false, error: 'Git operations failed: ' + gitResult.error };
            }
        }

