        try {
            let comment = jiraComment || '';
            if (prUrl) {
                comment += '\n\n*Story Test Branch PR*: ' + prUrl;
            }
            if (noCodeChanges) {
                comment += '\n\nℹ️ _Test code unchanged from previous run._';
